"use strict";function Delete(n){swal({title:"Wciśnij OK jeżeli chcesz trwale ususnąć grafikę",text:"Jeżeli wciśniesz OK, grafika zostanie trwale usunięta",icon:"warning",buttons:!0,dangerMode:!0}).then(function(t){t==!0&&(setTimeout(reloadPage,1e3),$.ajax({type:"DELETE",url:n,success:function(n){n.success?(toastr.info(n.message),setTimeout(reloadPage,3e3)):toastr.error(n.message)}}))})}function reloadPage(){window.location.reload()}